create extension if not exists pgcrypto;
create table if not exists public.recipes(id uuid primary key default gen_random_uuid(),user_id uuid not null,title text not null,category text not null check(category in('antipasti','primi','secondi','contorni','dolci')),description text,audio_url text,ingredients text[] default '{}',times_made integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.recipe_notes(id uuid primary key default gen_random_uuid(),recipe_id uuid not null references public.recipes(id) on delete cascade,user_id uuid not null,content text not null,position_x integer default 0,position_y integer default 0,color text default 'yellow',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.user_points(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id) on delete cascade,total_points integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.point_activities(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,activity_type text not null,points integer not null,description text,created_at timestamptz not null default now());
create table if not exists public.badges(id uuid primary key default gen_random_uuid(),name text unique not null,description text not null,icon text not null,requirement_type text not null,requirement_value integer not null,points_reward integer not null default 0,tier text not null default 'bronze',created_at timestamptz not null default now());
create table if not exists public.user_badges(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,badge_id uuid not null references public.badges(id) on delete cascade,earned_at timestamptz not null default now(),unique(user_id,badge_id));
alter table public.recipes enable row level security;alter table public.recipe_notes enable row level security;alter table public.user_points enable row level security;alter table public.point_activities enable row level security;alter table public.badges enable row level security;alter table public.user_badges enable row level security;
do $$begin
create policy recipes_select on public.recipes for select using(auth.uid()=user_id);exception when duplicate_object then null;end$$;
do $$begin create policy recipes_insert on public.recipes for insert with check(auth.uid()=user_id);exception when duplicate_object then null;end$$;
do $$begin create policy recipes_update on public.recipes for update using(auth.uid()=user_id);exception when duplicate_object then null;end$$;
do $$begin create policy recipes_delete on public.recipes for delete using(auth.uid()=user_id);exception when duplicate_object then null;end$$;
do $$begin create policy notes_all on public.recipe_notes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);exception when duplicate_object then null;end$$;
do $$begin create policy points_select on public.user_points for select using(auth.uid()=user_id);exception when duplicate_object then null;end$$;
do $$begin create policy activities_select on public.point_activities for select using(auth.uid()=user_id);exception when duplicate_object then null;end$$;
do $$begin create policy badges_select on public.badges for select using(true);exception when duplicate_object then null;end$$;
do $$begin create policy user_badges_select on public.user_badges for select using(auth.uid()=user_id);exception when duplicate_object then null;end$$;
create or replace function public.award_points(p_user_id uuid,p_activity_type text,p_points integer,p_description text default null) returns void language plpgsql security definer set search_path=public as $$begin insert into public.point_activities(user_id,activity_type,points,description)values(p_user_id,p_activity_type,p_points,p_description);insert into public.user_points(user_id,total_points)values(p_user_id,p_points)on conflict(user_id)do update set total_points=user_points.total_points+p_points,updated_at=now();end$$;
create or replace function public.award_recipe_points() returns trigger language plpgsql security definer set search_path=public as $$begin perform public.award_points(new.user_id,'recipe_created',10,'Created recipe: '||new.title);return new;end$$;
create or replace function public.award_note_points() returns trigger language plpgsql security definer set search_path=public as $$begin perform public.award_points(new.user_id,'note_created',2,'Added a note');return new;end$$;
create or replace function public.award_made_points() returns trigger language plpgsql security definer set search_path=public as $$begin if new.times_made>old.times_made then perform public.award_points(new.user_id,'recipe_made',5,'Made recipe: '||new.title);end if;return new;end$$;
drop trigger if exists recipe_created_points on public.recipes;create trigger recipe_created_points after insert on public.recipes for each row execute function public.award_recipe_points();
drop trigger if exists note_created_points on public.recipe_notes;create trigger note_created_points after insert on public.recipe_notes for each row execute function public.award_note_points();
drop trigger if exists recipe_made_points on public.recipes;create trigger recipe_made_points after update on public.recipes for each row execute function public.award_made_points();
insert into public.badges(name,description,icon,requirement_type,requirement_value,points_reward,tier)values('First Recipe','Create your first recipe','🍳','recipes_count',1,5,'bronze'),('Recipe Enthusiast','Create 5 recipes','👨‍🍳','recipes_count',5,15,'silver'),('Master Chef','Create 10 recipes','⭐','recipes_count',10,30,'gold'),('Note Taker','Add 10 notes','📝','notes_count',10,10,'bronze'),('Point Collector','Reach 100 points','💯','total_points',100,20,'bronze') on conflict(name)do nothing;
insert into storage.buckets(id,name,public)values('recipe-audio','recipe-audio',false)on conflict(id)do nothing;
